require_once __DIR__.'/includes/imap.php';
$test=null;$merchant=require_login();$pageTitle='Integrations';$pdo=db();$notice='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(($_POST['action']??'')==='test'){$row=$pdo->prepare('SELECT merchant_id,linked_email,imap_host,imap_port,google_app_password FROM merchant_accounts WHERE merchant_id=? ORDER BY id LIMIT 1');$row->execute([$merchant['id']]);$acc=$row->fetch();$test=$acc?imap_test_connection($acc):['ok'=>false,'message'=>'Save a receiving account before testing.'];$test['message']=$test['message'];}else{$label=trim((string)($_POST['account_label']??'Primary UPI'));$upi=trim((string)($_POST['upi_id']??''));$email=filter_var($_POST['linked_email']??'',FILTER_VALIDATE_EMAIL);$pass=preg_replace('/\s+/','',(string)($_POST['app_password']??''));if(!$email||($upiProblem=tg_validate_upi($upi))!==null||($pass!==''&&!preg_match('/^[A-Za-z0-9]{16}$/',$pass))){$notice=$upiProblem??'Enter a valid email, UPI ID, and (if updating) a 16-character app password.';}
